/**
 * CONTEXTE DES 66 LIVRES : de quoi comprendre avant de lire.
 * Complète lib/fiches-livres.ts (identité, plan). Données statiques.
 * ctx = le monde du livre · fil = ce qui s’y joue · th = grands thèmes ·
 * lire = comment le lire sans le trahir · appl = ce que Dieu peut en faire dans ma vie.
 */
export type Plus = { ctx: string; fil: string; th: string[]; lire: string; appl: string };

export const PLUS: Record<number, Plus> = {
  1: { ctx: 'Israël vient de sortir d’Égypte et marche vers la terre promise. Autour de lui, les peuples ont leurs récits de dieux en guerre et d’hommes créés pour servir. Genèse répond à une question simple : d’où venons-nous, qui est Dieu, et pourquoi le monde est-il brisé ?',
    fil: 'Un Dieu unique crée un monde bon, l’homme se détourne, le mal se répand. Dieu ne renonce pas : il choisit un homme, Abraham, pour que par sa famille toutes les nations soient bénies.',
    th: ['Création : le monde est voulu, bon, et confié à l’homme', 'Chute : le péché brise la relation avec Dieu et entre les humains', 'Alliance et promesse : Dieu s’engage, même quand son peuple échoue'],
    lire: 'C’est un récit fondateur, pas un manuel scientifique : on cherche d’abord ce que le texte affirme sur Dieu et sur l’homme. Remarque comment les promesses se transmettent d’une génération à l’autre malgré les fautes des patriarches.',
    appl: 'Dieu tient ses promesses malgré mes détours. Quelle promesse ai-je du mal à croire, et qu’est-ce qu’Abraham m’apprend sur la confiance ?' },
  2: { ctx: 'Après plusieurs siècles, les descendants de Jacob sont devenus un peuple nombreux et esclave en Égypte. Pharaon passe pour un dieu. Dieu révèle son nom à Moïse et se présente comme celui qui entend le cri des opprimés.',
    fil: 'Dieu libère son peuple par la Pâque et la traversée de la mer, puis conclut une alliance au Sinaï. Il donne la loi et le plan du tabernacle : il veut habiter au milieu de ceux qu’il a rachetés.',
    th: ['Délivrance : Dieu sauve avant de demander quoi que ce soit', 'Alliance : « Vous serez mon peuple » et la loi qui en découle', 'Présence : le tabernacle et la gloire de Dieu qui descend'],
    lire: 'Ne sépare pas la loi de la délivrance : les dix paroles commencent par « je t’ai fait sortir d’Égypte ». Dieu sauve d’abord, la loi dit ensuite comment vivre libres.',
    appl: 'De quoi Dieu m’a-t-il déjà délivré ? Ma vie obéissante est-elle une réponse à sa grâce, ou une tentative de la mériter ?' },
  3: { ctx: 'Israël campe au pied du Sinaï. Il doit apprendre à vivre avec un Dieu saint au milieu du camp. Les sacrifices, les prêtres et les règles de pureté organisent la vie du peuple pour qu’il puisse s’approcher sans mourir.',
    fil: 'Le péché sépare, mais Dieu donne le moyen de la réconciliation : un sacrifice qui prend la place du coupable. Le peuple est appelé à la sainteté, c’est-à-dire à être différent des nations autour de lui.',
    th: ['Sainteté : Dieu est autre, et son peuple lui appartient', 'Expiation : le sang couvre le péché (chapitre 16)', 'Vie quotidienne : la foi touche la nourriture, le travail, la justice'],
    lire: 'Lévitique se lit à la lumière de l’épître aux Hébreux : les sacrifices annoncent celui de Jésus. Les règles de pureté rituelle étaient pour Israël ; on retient ce qu’elles enseignent sur la sainteté de Dieu.',
    appl: 'Est-ce que je prends le péché au sérieux ? Et suis-je reconnaissant qu’un seul sacrifice suffise pour moi ?' },
  4: { ctx: 'Quarante ans de marche dans le désert, entre le Sinaï et les plaines de Moab. Une génération, sortie d’Égypte, refuse d’entrer dans la terre promise par peur. Elle meurt dans le désert ; ses enfants sont recensés à nouveau.',
    fil: 'Un peuple murmure, se révolte, est puni, mais Dieu le garde, le nourrit et le conduit. Les promesses passent à la génération suivante.',
    th: ['Incrédulité : la peur des géants vaut plus que la parole de Dieu', 'Patience de Dieu : manne, eau, nuée, il pourvoit chaque jour', 'Fidélité : il tient sa promesse malgré la faute de ses enfants'],
    lire: 'Le livre alterne recensements, lois et récits. Lis les récits comme des miroirs : Paul dit que ces événements « sont arrivés pour nous servir d’exemples » (1 Co 10).',
    appl: 'Où est-ce que je murmure au lieu de faire confiance ? Dieu m’a-t-il déjà nourri dans un désert que je traversais ?' },
  5: { ctx: 'Moïse parle à la nouvelle génération, devant le Jourdain, avant d’entrer dans le pays. Il lui redit la loi et l’histoire. Le texte a la forme des traités d’alliance de l’époque : rappel des bienfaits, règles, bénédictions et malédictions.',
    fil: 'Souviens-toi de ce que Dieu a fait, aime-le de tout ton cœur, obéis, et tu vivras. Le choix est posé : la vie ou la mort.',
    th: ['Écoute Israël : l’amour de Dieu est le premier commandement', 'Souvenir : ne pas oublier la délivrance', 'Choix : bénédiction ou malédiction selon la réponse'],
    lire: 'Remarque la répétition de « souviens-toi » et « garde-toi d’oublier ». Jésus cite trois fois Deutéronome pour répondre au diable au désert.',
    appl: 'Qu’ai-je tendance à oublier de ce que Dieu a fait ? Comment garder la mémoire vivante, dans la prière, un carnet, des repères ?' },
  6: { ctx: 'Vers 1400 av. J.-C. (ou plus tard selon les datations), Israël franchit le Jourdain et entre dans le pays de Canaan, habité par des cités puissantes aux pratiques violentes et idolâtres. Josué prend la suite de Moïse.',
    fil: 'Dieu donne le pays comme il l’avait promis. Le peuple doit rester fidèle ; la victoire vient de Dieu, pas de la force militaire.',
    th: ['Accomplissement : « Pas une parole ne tomba à terre »', 'Courage : Dieu est avec Josué comme il fut avec Moïse', 'Choix : « Moi et ma maison, nous servirons l’Éternel »'],
    lire: 'Les guerres de conquête posent question. Le texte présente un jugement de Dieu sur des peuples, limité à ce moment précis ; il ne donne aucune autorisation de violence aujourd’hui. Lis aussi Rahab, sauvée par sa foi.',
    appl: 'Quelle « terre » Dieu m’a-t-il promise et que je n’ose pas conquérir ? De quelle peur dois-je sortir pour avancer ?' },
  7: { ctx: 'Environ trois siècles entre Josué et les rois. Pas de roi, pas de gouvernement central : des chefs locaux, les juges, que Dieu suscite quand le peuple crie. Autour, la tentation constante des dieux cananéens.',
    fil: 'Un cycle qui se répète : le peuple abandonne Dieu, est opprimé, crie, Dieu envoie un libérateur, puis la paix, puis il recommence. Chaque tour est pire que le précédent.',
    th: ['Cycle du péché : l’oubli de Dieu mène à l’oppression', 'Libérateurs imparfaits : Dieu utilise des gens fragiles', '« Chacun faisait ce qui lui semblait bon » : le refrain tragique'],
    lire: 'Ces récits décrivent, ils ne prescrivent pas. Gédéon, Samson et Jephté ne sont pas des modèles à copier, mais des signes d’un peuple qui a besoin d’un vrai roi.',
    appl: 'Quels cycles se répètent dans ma vie ? Qu’est-ce qui me ramène à Dieu : la crise, ou son appel ?' },
  8: { ctx: 'À l’époque des juges, une famille de Bethléem émigre à Moab à cause de la famine. Noémi revient veuve, avec sa belle-fille moabite, Ruth. Une étrangère, sans droit, s’intègre dans le peuple de Dieu.',
    fil: 'Dieu veille sur une veuve et une étrangère à travers des gestes ordinaires : une glaneuse, un champ, un parent rédempteur. Il prépare ainsi la lignée de David.',
    th: ['Fidélité : l’attachement de Ruth à Noémi et au Dieu d’Israël', 'Rédempteur : Boaz rachète ce qui était perdu', 'Providence : Dieu agit dans le quotidien'],
    lire: 'C’est un petit récit qui éclaire la période sombre des Juges. Observe que le nom de Dieu est rarement cité, et pourtant il agit à chaque scène.',
    appl: 'Où Dieu agit-il discrètement dans ma vie, sans éclat ? Qui puis-je accueillir comme Boaz et Ruth l’ont fait ?' },
  9: { ctx: 'Vers 1100-1000 av. J.-C. Israël est menacé par les Philistins et réclame un roi pour être « comme les autres nations ». Samuel, dernier juge et prophète, est le pivot entre deux époques.',
    fil: 'Dieu donne un roi à contrecœur, Saül, qui échoue ; puis il choisit David, « un homme selon son cœur ». Le vrai roi se juge à son cœur, pas à sa taille.',
    th: ['Roi humain ou roi divin : qui règne vraiment ?', 'Le cœur : « L’homme regarde à l’apparence, Dieu regarde au cœur »', 'Dieu choisit les petits : David contre Goliath'],
    lire: 'Compare Saül et David : tous deux pèchent, mais l’un se justifie, l’autre se repent. Remarque ce que l’épreuve révèle de chacun.',
    appl: 'Sur quoi me juge-t-on, et sur quoi Dieu me juge-t-il ? Mon cœur est-il prêt à se laisser reprendre ?' },
  10: { ctx: 'Vers 1010-970 av. J.-C. David devient roi à Hébron, puis à Jérusalem. Israël atteint une grande puissance. Dieu promet à David une dynastie éternelle (7), puis le roi tombe dans l’adultère et le meurtre (11).',
    fil: 'Le plus grand roi d’Israël montre à la fois la grâce de Dieu et la gravité du péché. Les conséquences touchent sa famille, mais l’alliance tient.',
    th: ['Alliance davidique : un descendant régnera pour toujours', 'Péché et repentance : Nathan face au roi', 'Conséquences : le pardon n’efface pas toujours les suites'],
    lire: 'Lis le chapitre 7 lentement : c’est la promesse que le Nouveau Testament reprend pour Jésus. Puis le chapitre 11-12 : Dieu confronte, David reconnaît, et le Psaume 51 en est la prière.',
    appl: 'Quel péché ai-je minimisé ? Qui, comme Nathan, a le droit de me parler franchement ?' },
  11: { ctx: 'Vers 970-850 av. J.-C. Salomon bâtit le temple et reçoit la sagesse, mais ses mariages étrangers et son idolâtrie divisent ensuite le royaume en deux : Israël au nord, Juda au sud. Élie surgit dans un temps de grande apostasie.',
    fil: 'Un royaume brillant se fissure parce que le cœur de ses rois s’éloigne. Les prophètes appellent au retour, souvent seuls contre tous.',
    th: ['Temple : Dieu habite au milieu de son peuple', 'Sagesse qui s’égare : la richesse et le compromis', 'Prophètes : Élie contre Baal au Carmel'],
    lire: 'Chaque roi est évalué selon sa fidélité à Dieu, pas selon sa puissance. Lis ces jugements comme un fil rouge du livre.',
    appl: 'Où mon cœur se divise-t-il ? Qu’est-ce que je laisse entrer par petits compromis ?' },
  12: { ctx: 'Vers 850-560 av. J.-C. L’histoire des deux royaumes jusqu’à leur chute : Israël est déporté par l’Assyrie (722), Juda par Babylone (586). Les prophètes Élisée, Ésaïe et Jérémie parlent dans ce temps.',
    fil: 'Dieu avertit pendant des siècles avant de laisser tomber le jugement. L’exil n’est pas l’abandon : le dernier chapitre laisse une porte ouverte avec Jojakin libéré.',
    th: ['Avertissement : Dieu est patient mais juste', 'Fidélité de quelques-uns : Ézéchias, Josias', 'Exil : conséquence de siècles d’idolâtrie'],
    lire: 'Rois et Chroniques racontent la même période avec des regards différents : Rois explique la chute, Chroniques encourage ceux qui reviennent.',
    appl: 'Y a-t-il un avertissement de Dieu que je repousse depuis longtemps ?' },
  13: { ctx: 'Écrit après le retour d’exil, vers 450-400 av. J.-C. Le peuple rentre, reconstruit, mais se demande : avons-nous encore un avenir ? Le livre reprend l’histoire depuis Adam avec les généalogies pour affirmer que la promesse tient.',
    fil: 'Une relecture de l’histoire d’Israël centrée sur David, le temple et la fidélité. Le message : Dieu garde la lignée, et le culte rendu de tout cœur compte.',
    th: ['Généalogies : le peuple a une identité et une histoire', 'Temple et culte : la louange organisée par David', 'Retour à Dieu : les rois qui se repentent sont restaurés'],
    lire: 'Les listes de noms ne sont pas du remplissage : elles disent à des exilés revenus qu’ils ont une place dans la promesse.',
    appl: 'Dieu connaît mon nom et mon histoire. Comment ma vie de louange est-elle devenue routine, et comment la ranimer ?' },
  14: { ctx: 'Le même auteur que 1 Chroniques, vers 450-400 av. J.-C., raconte l’histoire de Salomon jusqu’à l’exil en insistant sur le temple et sur les réveils des rois pieux.',
    fil: 'Quand Juda se tourne vers Dieu, il est béni ; quand il s’éloigne, il tombe. Même après la chute, Cyrus ouvre la porte du retour.',
    th: ['« Si mon peuple s’humilie… » (7:14)', 'Réveils : Asa, Josaphat, Ézéchias, Josias', 'Espoir : l’édit de Cyrus pour reconstruire'],
    lire: 'Compare avec les livres des Rois : Chroniques se concentre sur Juda et sur ce qui donne de l’espérance après le malheur.',
    appl: 'Le retour est toujours possible. Quel pas d’humilité Dieu me demande-t-il aujourd’hui ?' },
  15: { ctx: 'Vers 538-520 av. J.-C. Cyrus, roi de Perse, autorise les Juifs à rentrer. Zorobabel mène un premier groupe, puis Esdras arrive vers 458 avec la loi de Dieu. Le temple est reconstruit, plus modeste que celui de Salomon.',
    fil: 'Dieu fait revenir son peuple, comme il l’avait annoncé par Jérémie. Il faut rebâtir le temple, puis revenir à la Parole.',
    th: ['Fidélité de Dieu à ses promesses d’exil et de retour', 'Reconstruction : malgré l’opposition', 'Parole : Esdras étudie, pratique et enseigne la loi'],
    lire: 'La liste de ceux qui reviennent montre que Dieu connaît chaque famille. Ne saute pas ces noms.',
    appl: 'Esdras a « appliqué son cœur » à étudier, pratiquer, enseigner. Dans quel ordre le fais-je ?' },
  16: { ctx: 'Vers 445 av. J.-C. Néhémie, échanson du roi de Perse, apprend que les murailles de Jérusalem sont en ruine. Il obtient une mission, et reconstruit en 52 jours malgré les moqueries et les menaces.',
    fil: 'Un homme qui prie, planifie et agit voit Dieu rebâtir. Puis le peuple se rassemble autour de la loi dans un réveil, et doit rester fidèle.',
    th: ['Prière et action : il prie, puis il se met au travail', 'Opposition : moqueries, menaces, intrigues', 'Réveil : la lecture de la loi et la fête'],
    lire: 'C’est un modèle de leadership. Remarque comment il commence toujours par la prière avant chaque décision.',
    appl: 'Quelle muraille est en ruine dans ma vie ou mon entourage ? Qu’est-ce que Dieu m’appelle à rebâtir, une pierre à la fois ?' },
  17: { ctx: 'Vers 480-470 av. J.-C., sous le roi perse Xerxès (Assuérus). Des Juifs restés en Perse sont menacés d’extermination par Haman. Esther, devenue reine, doit choisir entre se taire et risquer sa vie.',
    fil: 'Le nom de Dieu n’apparaît jamais, et pourtant il dirige tout : les coïncidences, le renversement, le salut de son peuple.',
    th: ['Providence : Dieu agit sans qu’on le nomme', 'Courage : « Qui sait si tu n’es pas parvenue à la royauté pour un temps comme celui-ci ? »', 'Renversement : le piège de Haman se retourne contre lui'],
    lire: 'Cherche les « hasards » du livre : une reine déposée, un complot découvert, une nuit sans sommeil. Le narrateur les place exprès.',
    appl: 'Pour quel « temps comme celui-ci » Dieu m’a-t-il placé là où je suis ?' },
  18: { ctx: 'Probablement très ancien, dans le monde des patriarches. Job est un homme juste et riche qui perd tout. Ses amis lui répètent que la souffrance est toujours le fruit d’une faute. Le livre est une grande discussion sur le mal et sur Dieu.',
    fil: 'Job crie, doute, proteste, mais ne renonce pas à Dieu. Dieu répond à la fin, non par des explications, mais par sa présence et sa grandeur.',
    th: ['Souffrance du juste : elle n’est pas toujours une punition', 'Les amis : de mauvais consolateurs qui parlent trop', 'Dieu répond : il montre sa sagesse sans tout expliquer'],
    lire: 'Les discours des amis contiennent de belles vérités, mais mal appliquées : Dieu les reprend à la fin. Ne cite pas un verset de ces discours sans vérifier qui parle.',
    appl: 'Face à la souffrance d’un proche, ai-je plus besoin d’expliquer ou de rester présent ?' },
  19: { ctx: 'Recueil de 150 chants et prières écrits sur environ mille ans, de Moïse à l’exil. David en est l’auteur principal. Les psaumes étaient chantés au temple et dans la vie quotidienne : ils disent la louange, la plainte, la repentance, la confiance.',
    fil: 'Cinq livres de prières qui conduisent de la souffrance à la louange. Ils montrent comment parler à Dieu avec honnêteté, et ce qu’il fait pour ceux qui crient à lui.',
    th: ['Louange : Dieu est grand, bon, fidèle', 'Plainte : crier honnêtement à Dieu est permis', 'Roi messianique : plusieurs psaumes annoncent le Christ (2, 22, 110)'],
    lire: 'Identifie le type de psaume : louange, plainte, repentance, sagesse, royal. Lis le psaume à voix haute, et remarque le poème hébreu : le parallélisme, deux lignes qui disent la même chose autrement.',
    appl: 'Les psaumes donnent des mots quand je n’en ai pas. Quel psaume correspond à ce que je vis aujourd’hui ?' },
  20: { ctx: 'Recueil de sagesse attribué en grande partie à Salomon, vers 950 av. J.-C., avec d’autres sages ajoutés plus tard. La sagesse en Israël n’est pas une théorie : c’est l’art de bien vivre devant Dieu dans les décisions ordinaires.',
    fil: 'La crainte de l’Éternel est le commencement de la sagesse. Le livre oppose la voie de la sagesse et celle de la folie, avec des conseils concrets sur la parole, l’argent, le travail, la famille.',
    th: ['Crainte de Dieu : le point de départ de la sagesse', 'Parole : la langue donne la vie ou la mort', 'Travail et argent : diligence, générosité, honnêteté'],
    lire: 'Les proverbes sont des principes généraux, pas des promesses automatiques. Un proverbe isolé ne dit pas tout : lis-en plusieurs sur un même sujet.',
    appl: 'Quel domaine de ma vie, parole, argent, colère, demande de la sagesse ? Un proverbe par jour suffit pour commencer.' },
  21: { ctx: 'Un sage, souvent identifié à Salomon, cherche le sens de la vie « sous le soleil » : travail, plaisir, richesse, savoir. Il constate que tout est « vanité », c’est-à-dire un souffle, sans Dieu.',
    fil: 'Tout ce qui est limité à ce monde déçoit. Mais le sage conclut : craindre Dieu et garder ses commandements, car tout vient de lui et sera jugé par lui.',
    th: ['Vanité : sans Dieu, tout fuit comme un souffle', 'Temps : « Il y a un temps pour tout »', 'Don de Dieu : manger, travailler, se réjouir avec reconnaissance'],
    lire: 'Le ton paraît pessimiste, mais le sage décrit la vie sans Dieu avant de donner sa conclusion. Ne cite pas le livre sans aller jusqu’à la fin.',
    appl: 'Qu’est-ce que je poursuis qui ne peut pas me rassasier ? Quelle joie simple puis-je recevoir aujourd’hui comme un don ?' },
  22: { ctx: 'Chant d’amour attribué à Salomon, dans la tradition de la poésie orientale. Deux amants se cherchent, se désirent, s’admirent. Le texte célèbre l’amour humain comme un don de Dieu.',
    fil: 'L’amour entre un homme et une femme est beau, fort, et à garder dans son cadre. La tradition juive et chrétienne y a vu aussi l’image de l’amour de Dieu pour son peuple.',
    th: ['Amour conjugal : le désir est un don de Dieu', 'Fidélité : « L’amour est fort comme la mort »', 'Image : l’amour de Dieu et de l’Église (lecture traditionnelle)'],
    lire: 'Lis-le comme de la poésie, avec ses images orientales. On n’en tire pas une règle par verset : on se laisse enseigner sur la valeur et la pureté de l’amour.',
    appl: 'Si je suis marié : comment dire mon amour concrètement ? Si je suis célibataire : comment honorer ce que Dieu a fait beau ?' },
  23: { ctx: 'Ésaïe prophétise à Jérusalem vers 740-700 av. J.-C., sous quatre rois de Juda, dans l’ombre de l’Assyrie. Les chapitres 40-66 parlent aussi à un peuple exilé, ou à venir, qui a besoin de consolation.',
    fil: 'Jugement sur l’injustice et l’idolâtrie, puis consolation : Dieu viendra sauver. Un serviteur souffrant portera nos péchés, et un règne de paix s’installe.',
    th: ['Sainteté de Dieu : « Saint, saint, saint » (6)', 'Serviteur souffrant : le chapitre 53 annonce la croix', 'Consolation : « Consolez mon peuple » (40)'],
    lire: 'Le livre est long et change de ton. Commence par 1, 6, 9, 40, 53, 55 et 65-66 pour saisir le mouvement. Le Nouveau Testament cite Ésaïe plus que tout autre prophète.',
    appl: 'Dieu parle ici à des gens qui se sentent perdus. Quelle consolation ai-je besoin d’entendre, et où ai-je besoin d’être repris ?' },
  24: { ctx: 'Jérémie prophétise de 627 à 586 av. J.-C., jusqu’à la chute de Jérusalem. Il est rejeté, emprisonné, jeté dans une citerne. Il pleure sur son peuple qui refuse de revenir à Dieu.',
    fil: 'Dieu appelle à se repentir, le peuple refuse, le jugement tombe. Mais Dieu promet une nouvelle alliance, écrite dans le cœur.',
    th: ['Prophète en larmes : il aime ceux à qui il annonce le jugement', 'Fausse sécurité : « Le temple de l’Éternel ! » ne sauve pas', 'Nouvelle alliance : une loi mise dans le cœur (31)'],
    lire: 'Le livre n’est pas dans l’ordre chronologique. Lis-le par thèmes : appel (1), temple (7), potier (18), lettre aux exilés (29), nouvelle alliance (31).',
    appl: 'Dieu voit mon cœur, pas mes pratiques. Qu’est-ce qui a besoin d’être écrit en moi, plutôt que seulement pratiqué ?' },
  25: { ctx: 'Cinq poèmes composés après la destruction de Jérusalem en 586 av. J.-C., probablement par Jérémie ou un témoin. La ville est en ruine, le temple brûlé, le peuple déporté ou affamé.',
    fil: 'On peut pleurer devant Dieu. Le livre ose dire la douleur, puis au centre se trouve une lueur : « Les bontés de l’Éternel ne sont pas épuisées ».',
    th: ['Deuil : la douleur est exprimée sans la masquer', 'Aveu : le peuple reconnaît sa part de faute', 'Espérance : « Grande est ta fidélité » (3:22-23)'],
    lire: 'Les poèmes suivent l’alphabet hébreu : l’ordre même du chagrin. Lis lentement, ne cherche pas à consoler trop vite.',
    appl: 'Ai-je laissé Dieu entendre ma tristesse sans la maquiller ? Quelle fidélité de Dieu puis-je nommer, même dans la nuit ?' },
  26: { ctx: 'Ézéchiel, prêtre déporté à Babylone en 597 av. J.-C., prophétise parmi les exilés. Il voit la gloire de Dieu quitter le temple, puis annonce un retour. Ses visions et ses gestes symboliques sont frappants.',
    fil: 'Dieu juge l’idolâtrie, mais il n’abandonne pas ses exilés : il les rassemble, leur donne un cœur neuf et son Esprit. Les ossements desséchés revivent.',
    th: ['Gloire de Dieu : elle part et elle revient', 'Cœur nouveau : « Je mettrai mon Esprit en vous » (36)', 'Responsabilité personnelle : chacun répond de sa vie (18)'],
    lire: 'Beaucoup d’images symboliques : lis-les comme des tableaux qui disent une vérité, sans chercher à les déchiffrer comme un code. Les chapitres 40-48 décrivent un temple futur dont l’interprétation est débattue.',
    appl: 'Dieu peut redonner vie à ce qui paraît sec. Quel domaine de ma vie lui ai-je déclaré sans espoir ?' },
  27: { ctx: 'Daniel est déporté à Babylone vers 605 av. J.-C. jeune encore, et sert à la cour de rois étrangers pendant plus de soixante ans. Il reste fidèle à Dieu dans un empire hostile.',
    fil: 'Dieu règne sur les empires. Les récits (1-6) montrent la fidélité de Daniel et de ses amis, les visions (7-12) montrent la succession des royaumes et la victoire finale du Fils de l’homme.',
    th: ['Fidélité : vivre sa foi dans une culture opposée', 'Souveraineté : Dieu change les temps et les saisons', 'Fils de l’homme : un règne qui ne passera pas (7)'],
    lire: 'Le livre alterne récits et visions. Les visions sont interprétées de plusieurs manières par les chrétiens : concentre-toi d’abord sur le message d’espérance.',
    appl: 'Où suis-je appelé à rester fidèle dans un milieu qui ne partage pas ma foi ? Qu’est-ce que Dieu change, même quand les puissants décident ?' },
  28: { ctx: 'Osée prophétise dans le royaume du nord, vers 750-722 av. J.-C., avant la chute de Samarie. Dieu lui demande d’épouser une femme infidèle, Gomer, pour illustrer l’infidélité d’Israël.',
    fil: 'Israël a trahi Dieu comme une épouse infidèle, mais Dieu continue à l’aimer, la ramène, la restaure.',
    th: ['Alliance comme mariage : Dieu est un époux fidèle', 'Infidélité : l’idolâtrie est une trahison', 'Amour tenace : « Comment t’abandonnerais-je ? » (11)'],
    lire: 'La vie d’Osée est le message : lis son histoire avec Gomer à côté des oracles. Remarque l’alternance entre jugement et tendresse.',
    appl: 'Dieu m’aime quand je me détourne. Comment ai-je répondu à cet amour, par habitude ou par reconnaissance ?' },
  29: { ctx: 'Joël, à une date débattue, décrit une invasion de sauterelles qui ravage le pays et y voit un avertissement du jour de l’Éternel. Il appelle à la repentance.',
    fil: 'Le malheur devient appel à revenir à Dieu, qui promet de restaurer et d’envoyer son Esprit sur tous.',
    th: ['Jour de l’Éternel : un jugement qui approche', 'Repentance : « Déchirez vos cœurs et non vos vêtements »', 'Esprit répandu : Pierre cite Joël à la Pentecôte'],
    lire: 'Lis le chapitre 2:12-32 en entier, puis Actes 2 : tu verras comment la promesse s’accomplit.',
    appl: 'Quand tout est secoué, est-ce que je reviens à Dieu ? Quel signe extérieur remplace chez moi un vrai retour du cœur ?' },
  30: { ctx: 'Amos, éleveur et cultivateur de Juda, prophétise au royaume du nord vers 760 av. J.-C., dans une période de prospérité où les riches écrasent les pauvres tout en pratiquant le culte.',
    fil: 'Dieu rejette un culte sans justice. Il annonce le jugement sur les injustices, mais finit par promettre de relever la hutte de David.',
    th: ['Justice sociale : Dieu voit l’opprimé', 'Culte vide : « Que le droit jaillisse comme l’eau »', 'Restauration : la hutte de David relevée'],
    lire: 'Amos est direct, parfois dur. Remarque qu’il parle aux nations voisines avant d’arriver à Israël : personne n’y échappe.',
    appl: 'Ma foi touche-t-elle mon portefeuille, mon travail, ma façon de traiter les plus faibles ?' },
  31: { ctx: 'Le plus court livre de l’Ancien Testament, un seul chapitre, vers 840 ou 585 av. J.-C. Édom, peuple voisin issu d’Ésaü, a profité de la chute de Jérusalem.',
    fil: 'Dieu juge l’orgueil d’Édom qui a ricané sur la détresse de son frère. À la fin, le royaume appartient à l’Éternel.',
    th: ['Orgueil : « L’orgueil de ton cœur t’a trompé »', 'Fraternité trahie : se réjouir du malheur d’autrui', 'Royauté de Dieu : « Le règne sera à l’Éternel »'],
    lire: 'Lis-le en deux minutes, puis relis Genèse 25-33 pour comprendre l’histoire d’Ésaü et de Jacob derrière ce reproche.',
    appl: 'Me suis-je déjà réjoui, même en secret, de la chute de quelqu’un ? Que dit Dieu de ce plaisir ?' },
  32: { ctx: 'Jonas prophétise à Israël au VIIIe siècle av. J.-C. Dieu l’envoie à Ninive, capitale de l’Assyrie, ennemie cruelle d’Israël. Jonas s’enfuit dans la direction opposée.',
    fil: 'Un prophète qui refuse la grâce pour ses ennemis est repris par un Dieu qui s’intéresse à Ninive et à ses animaux. Le livre se termine sur une question, sans réponse de Jonas.',
    th: ['Mission : Dieu aime aussi les peuples qu’on déteste', 'Fuite : on ne s’échappe pas de sa présence', 'Compassion : Dieu est « lent à la colère et riche en bonté »'],
    lire: 'La question finale est pour le lecteur : suis-je Jonas ? Jésus cite le signe de Jonas comme une annonce de sa résurrection.',
    appl: 'Y a-t-il quelqu’un que je préférerais ne pas voir pardonné ? Qu’est-ce que Dieu me dit à travers ce livre ?' },
  33: { ctx: 'Michée prophétise à Juda vers 740-700 av. J.-C., en même temps qu’Ésaïe. Il vient de la campagne et dénonce les dirigeants corrompus de Jérusalem et de Samarie.',
    fil: 'Jugement sur l’injustice, puis promesse : un chef naîtra à Bethléem. Dieu résume ce qu’il demande : pratiquer la justice, aimer la bonté, marcher humblement avec lui.',
    th: ['Justice : les riches qui volent les pauvres sont condamnés', 'Bethléem : le Messie naîtra là (5:1)', 'Humilité : « Marcher humblement avec ton Dieu » (6:8)'],
    lire: 'Le livre alterne trois fois jugement et espoir. Lis 5:1 avec Matthieu 2 : les prêtres le citent pour répondre aux mages.',
    appl: 'Justice, bonté, humilité : laquelle des trois est la plus fragile chez moi aujourd’hui ?' },
  34: { ctx: 'Nahoum prophétise vers 663-612 av. J.-C., environ un siècle après Jonas. Ninive, qui s’était repentie, est redevenue violente. Le livre annonce sa chute, qui arrive en 612.',
    fil: 'Dieu n’est pas indifférent à la violence des empires. Il est patient, mais il juge, et c’est une consolation pour les opprimés.',
    th: ['Justice de Dieu : il n’innocente pas le coupable', 'Refuge : « L’Éternel est bon, il est un refuge au jour de la détresse »', 'Fin des empires : aucune puissance ne dure'],
    lire: 'Lis-le avec Jonas : ce que Dieu avait épargné par repentance, il le juge après l’avoir vu se corrompre à nouveau.',
    appl: 'Face à une injustice qui m’écrase, puis-je confier à Dieu ce que je ne peux pas régler moi-même ?' },
  35: { ctx: 'Habacuc prophétise vers 609-598 av. J.-C., à l’approche de l’invasion babylonienne. Il ne parle pas au peuple : il interpelle Dieu sur l’injustice qu’il voit et sur le moyen choisi pour la punir.',
    fil: 'Le prophète demande « Pourquoi ? » deux fois, Dieu répond, puis il finit sur un chant de confiance : même sans récolte, il se réjouira dans l’Éternel.',
    th: ['Questions honnêtes : Dieu accepte le « pourquoi »', 'La foi : « Le juste vivra par sa foi » (2:4)', 'Confiance sans garantie : « Quand le figuier ne fleurira pas… »'],
    lire: 'Paul cite 2:4 dans Romains et Galates. Remarque la structure : plainte, réponse, plainte, réponse, prière.',
    appl: 'Quel « pourquoi » ai-je gardé pour moi ? Puis-je le dire à Dieu, et attendre sa réponse ?' },
  36: { ctx: 'Sophonie prophétise à Juda vers 640-609 av. J.-C., sous le roi Josias. Il annonce le jour de l’Éternel contre Juda et les nations.',
    fil: 'Le jugement est certain, mais il est suivi d’un reste humble que Dieu garde, et d’un chant : l’Éternel est au milieu de toi et se réjouit à ton sujet.',
    th: ['Jour de l’Éternel : jugement universel', 'Reste humble : ceux qui cherchent l’Éternel', 'Joie de Dieu : « Il chantera avec allégresse à ton sujet »'],
    lire: 'La dernière page est l’une des plus tendres de l’Ancien Testament. Lis-la sans te presser.',
    appl: 'Imagine que Dieu chante sur toi. Qu’est-ce que cela change dans l’image que tu as de lui ?' },
  37: { ctx: 'Aggée prophétise en 520 av. J.-C. Les exilés sont revenus depuis dix-huit ans et ont arrêté la reconstruction du temple pour s’occuper de leurs maisons.',
    fil: 'Dieu appelle à remettre ses priorités en ordre : bâtir sa maison d’abord. Le peuple obéit, et Dieu promet que la gloire du second temple dépassera celle du premier.',
    th: ['Priorités : « Considérez vos voies »', 'Obéissance : le peuple se remet au travail', 'Promesse : « Je suis avec vous »'],
    lire: 'Quatre messages datés avec précision. Remarque que Dieu les donne en quelques mois : il agit vite quand le peuple écoute.',
    appl: 'Qu’est-ce que j’ai remis à plus tard, alors que Dieu me l’a clairement demandé ?' },
  38: { ctx: 'Zacharie prophétise dès 520 av. J.-C., en même temps qu’Aggée. Il encourage les rapatriés et annonce un roi humble sur un âne et un berger frappé.',
    fil: 'Huit visions nocturnes disent que Dieu est à l’œuvre. Puis des oracles annoncent un roi et un berger : plusieurs sont repris dans les Évangiles.',
    th: ['Encouragement : « Ce n’est ni par la puissance, ni par la force, mais par mon Esprit » (4:6)', 'Roi humble : l’entrée à Jérusalem sur un âne (9:9)', 'Berger frappé : la passion annoncée (13:7)'],
    lire: 'Le langage est symbolique, parfois difficile. Garde les chapitres 4, 9 et 12-14 comme repères, et lis-les avec les récits de la Semaine sainte.',
    appl: 'Où est-ce que je compte sur mes forces ? Qu’est-ce que Dieu veut faire par son Esprit dans ma situation ?' },
  39: { ctx: 'Malachie est le dernier prophète de l’Ancien Testament, vers 450-430 av. J.-C. Le temple est reconstruit, mais le peuple est tiède : offrandes de second choix, prêtres indifférents, divorces faciles.',
    fil: 'Dieu rappelle son amour, reprend la tiédeur, et promet un messager qui préparera la venue du Seigneur. Puis le silence de quatre siècles commence.',
    th: ['Amour de Dieu : « Je vous ai aimés »', 'Tiédeur : donner à Dieu ce qui reste', 'Messager : Jean-Baptiste annoncé (3:1, 4:5)'],
    lire: 'Le livre utilise des questions et des réponses : le peuple demande « En quoi ? » et Dieu répond. Ensuite tourne la page : Matthieu commence là où Malachie finit.',
    appl: 'Qu’est-ce que je donne à Dieu : le meilleur, ou les restes de mon temps et de mes forces ?' },
  40: { ctx: 'Écrit vers 60-70 de notre ère, probablement pour des chrétiens d’origine juive. Matthieu, ancien collecteur d’impôts, présente Jésus comme le Messie annoncé par les prophètes, avec de nombreuses citations de l’Ancien Testament.',
    fil: 'Jésus est le roi promis à Israël. Il enseigne dans cinq grands discours, meurt, ressuscite, et envoie ses disciples faire des disciples de toutes les nations.',
    th: ['Royaume des cieux : Dieu règne là où Jésus est suivi', 'Accomplissement : « afin que s’accomplisse ce qui avait été dit »', 'Disciples : une communauté qui obéit à tout ce qu’il a commandé'],
    lire: 'Remarque les cinq discours, chacun terminé par « Quand Jésus eut achevé ces paroles » : sermon sur la montagne (5-7), mission (10), paraboles (13), vie d’Église (18), fin des temps (24-25).',
    appl: 'Jésus parle à des disciples, pas seulement à des auditeurs. Quel commandement du sermon sur la montagne vais-je mettre en pratique cette semaine ?' },
  41: { ctx: 'Écrit vers 55-65 de notre ère à Rome, pour des chrétiens non juifs menacés de persécution. Marc, compagnon de Pierre, est le plus court et le plus rapide des Évangiles.',
    fil: 'Jésus agit avec autorité, puis annonce qu’il doit souffrir. Le livre tourne autour de la confession de Pierre à Césarée (8:29) : le Christ est un serviteur qui donne sa vie.',
    th: ['Serviteur souffrant : « Le Fils de l’homme est venu pour servir »', 'Secret messianique : Jésus demande souvent de se taire', 'Suivre : le coût du disciple'],
    lire: 'Marc va vite : « aussitôt » revient souvent. Lis-le d’une traite en une heure, tu verras l’ensemble avant d’étudier le détail.',
    appl: 'Jésus est venu pour servir. Où suis-je appelé à servir plutôt qu’à être servi ?' },
  42: { ctx: 'Écrit vers 60-80 de notre ère par Luc, médecin et compagnon de Paul, pour Théophile et des lecteurs non juifs. Il se présente comme un historien qui a « tout vérifié depuis les origines ».',
    fil: 'Jésus est le sauveur de tous, et particulièrement des petits : pauvres, pécheurs, femmes, étrangers. Il monte à Jérusalem pour souffrir, puis ressuscite.',
    th: ['Compassion : pour les perdus, les malades, les exclus', 'Joie : naissances, repas, retour du fils perdu', 'Prière et Esprit : Jésus prie souvent'],
    lire: 'Luc a des récits qu’on ne trouve qu’ici : le bon Samaritain, le fils prodigue, Zachée. Lis le voyage vers Jérusalem (9:51-19:27) comme une école.',
    appl: 'Qui est « le perdu » que Jésus me demande de chercher, comme le berger de la brebis ?' },
  43: { ctx: 'Écrit vers 85-95 de notre ère par l’apôtre Jean, pour que le lecteur croie que Jésus est le Christ, le Fils de Dieu, et ait la vie. Il choisit sept signes et sept « Je suis » parmi d’autres.',
    fil: 'La Parole éternelle s’est faite chair. Jésus révèle le Père, est rejeté par les siens, donne sa vie, et ressuscite : croire, c’est avoir la vie.',
    th: ['Parole faite chair : Jésus est Dieu venu parmi nous', 'Je suis : le pain, la lumière, la porte, le berger, la vie, le chemin, la vigne', 'Croire : le verbe-clé du livre'],
    lire: 'Lis le prologue (1:1-18) lentement, puis les sept signes. Le chapitre 20:30-31 donne le but du livre : tu sauras alors pourquoi chaque récit est là.',
    appl: 'Jean demande : crois-tu ? Quel « Je suis » de Jésus ai-je le plus besoin d’entendre aujourd’hui ?' },
  44: { ctx: 'Écrit vers 62 de notre ère par Luc, suite de son Évangile. Il raconte les premières années de l’Église, de Jérusalem à Rome, sur environ trente ans.',
    fil: 'L’Esprit est donné, l’Évangile traverse les frontières : Jérusalem, Judée, Samarie, jusqu’aux extrémités de la terre. Pierre puis Paul en sont les porte-voix.',
    th: ['Esprit : la puissance de la mission', 'Témoignage : « Vous serez mes témoins »', 'Frontières franchies : Juifs, Samaritains, nations'],
    lire: 'Le verset 1:8 donne le plan. Remarque que le livre ne se termine pas : Paul prêche à Rome « sans obstacle » et l’histoire continue.',
    appl: 'Le même Esprit agit aujourd’hui. Qui puis-je rejoindre là où je suis, comme les premiers chrétiens ?' },
  45: { ctx: 'Paul écrit de Corinthe, vers 56-58, à des chrétiens de Rome qu’il n’a pas encore rencontrés. La ville est le centre de l’empire. L’Église mêle des croyants juifs et non juifs qui se jugent mutuellement.',
    fil: 'Tous sont pécheurs, tous sont sauvés par la grâce par la foi en Christ. Cette bonne nouvelle forme un seul peuple, qui vit désormais dans l’Esprit.',
    th: ['Justification : déclaré juste par grâce, par la foi', 'Esprit : la vie nouvelle du chapitre 8', 'Unité : Juifs et nations ensemble'],
    lire: 'Romains est un raisonnement continu : suis la logique d’un chapitre au suivant sans isoler un verset. Les « donc » et « car » sont des charnières.',
    appl: 'Suis-je assuré de n’être « sous aucune condamnation » (8:1) ? Quel frère ou sœur ai-je jugé alors que Dieu l’a accueilli ?' },
  46: { ctx: 'Paul écrit d’Éphèse vers 55 à l’Église de Corinthe, grande ville portuaire, riche et morale relâchée, qu’il a fondée. Il répond à des rapports de divisions et à une lettre de questions.',
    fil: 'L’Église est divisée, tolère le péché et abuse des dons. Paul corrige, puis rappelle l’essentiel : l’amour, et la résurrection de Christ.',
    th: ['Unité : un seul corps, plusieurs membres', 'Amour : le chapitre 13 est au cœur des dons', 'Résurrection : sans elle, la foi est vaine (15)'],
    lire: 'La lettre répond à des questions précises. Essaie d’imaginer la question avant de lire la réponse de Paul.',
    appl: 'Dans mon Église, est-ce que je cherche d’abord à recevoir ou à édifier ? L’amour est-il visible dans ma façon d’utiliser mes dons ?' },
  47: { ctx: 'Paul écrit de Macédoine vers 56, après une période tendue avec Corinthe. Certains contestent son autorité d’apôtre. Il défend son ministère sans s’enorgueillir.',
    fil: 'Le ministère authentique passe par la faiblesse. Paul invite à se réconcilier, à donner généreusement et à ne pas se laisser séduire par de faux apôtres.',
    th: ['Consolation : Dieu console pour que nous consolions', 'Faiblesse : « Ma grâce te suffit »', 'Générosité : donner avec joie'],
    lire: 'C’est la lettre la plus personnelle de Paul. Remarque comment il passe de la tendresse à l’ironie, parce que l’enjeu est le cœur des Corinthiens.',
    appl: 'Quelle faiblesse ai-je honte de montrer ? Qu’est-ce que Dieu veut faire de ma fragilité ?' },
  48: { ctx: 'Paul écrit aux Églises de Galatie (en Asie Mineure), probablement vers 48-55. Des enseignants disent aux non-Juifs devenus chrétiens qu’ils doivent aussi être circoncis et observer la loi pour être sauvés.',
    fil: 'La justification est par la foi en Christ seul, sans œuvres de la loi. Qui ajoute quoi que ce soit abandonne l’Évangile. La liberté vient avec l’Esprit et son fruit.',
    th: ['Évangile : un seul, sans ajout', 'Liberté : « Christ nous a libérés pour que nous soyons libres »', 'Esprit : il produit un fruit, pas un règlement'],
    lire: 'Paul est ici très vif, il n’y a aucun remerciement au début. Remarque sa colère et sa raison : on touche à l’Évangile même.',
    appl: 'Où est-ce que je rajoute des conditions à la grâce, pour moi ou pour les autres ?' },
  49: { ctx: 'Paul écrit depuis sa prison à Rome, vers 60-62, à des Églises d’Asie dont Éphèse, ville du culte d’Artémis et de la magie. La lettre a un ton très haut : elle est l’une des plus grandioses du Nouveau Testament.',
    fil: 'La première moitié dit ce que Dieu a fait en Christ : choisis, sauvés, unis. La seconde dit comment vivre : unité, vie nouvelle, famille, combat spirituel.',
    th: ['Grâce : sauvés par grâce, par la foi (2:8-9)', 'Église : un seul corps, Juifs et non-Juifs', 'Combat : l’armure de Dieu (6)'],
    lire: 'Les trois premiers chapitres sont presque une longue prière. Respecte la charnière : « Je vous exhorte donc » (4:1) commence la pratique.',
    appl: 'Est-ce que ma façon de vivre au quotidien est à la hauteur de ce que Dieu a fait pour moi ? Quel point du chapitre 4 vais-je travailler ?' },
  50: { ctx: 'Paul écrit de prison vers 61 à l’Église de Philippes, première Église fondée en Europe (Actes 16), qui l’a soutenu par ses dons. La lettre est un remerciement, une consolation, un appel à l’unité.',
    fil: 'La joie ne dépend pas des circonstances : Paul est enchaîné et se réjouit. Christ s’est abaissé, Dieu l’a élevé : voilà le modèle de l’humilité.',
    th: ['Joie : mentionnée une quinzaine de fois', 'Humilité de Christ : l’hymne du chapitre 2', 'Contentement : « J’ai appris à être content »'],
    lire: 'Garde en tête que Paul écrit depuis la prison. Chaque mot de joie en prend plus de poids.',
    appl: 'Qu’est-ce qui me prive de joie aujourd’hui ? Quel changement de regard Paul me suggère-t-il ?' },
  51: { ctx: 'Paul écrit de prison vers 60-62 à l’Église de Colosses, qu’il n’a pas fondée. Un enseignement mêlait philosophie, ascétisme, culte des anges et régimes spéciaux.',
    fil: 'Christ est suffisant : créateur, réconciliateur, tête de l’Église. Rien ne s’ajoute à lui. Puis Paul décrit la vie nouvelle concrète à la maison et au travail.',
    th: ['Primauté du Christ : l’hymne de 1:15-20', 'Suffisance : en lui nous sommes accomplis', 'Vie nouvelle : se dévêtir de l’ancien, se revêtir du nouveau'],
    lire: 'Le thème est proche d’Éphésiens, que Paul envoie en même temps. Lis les deux à la suite.',
    appl: 'Qu’est-ce que je cherche en plus de Christ pour me sentir spirituel ou en sécurité ?' },
  52: { ctx: 'Paul écrit de Corinthe vers 50-51 à une jeune Église de Thessalonique, fondée quelques semaines plus tôt et déjà persécutée. Ce sont probablement ses premiers écrits conservés.',
    fil: 'Paul encourage une Église jeune : il rappelle ce qu’elle a vécu, console ceux qui ont perdu des proches, et enseigne que Jésus reviendra.',
    th: ['Persévérance : foi, amour et espérance', 'Retour du Christ : « Le Seigneur lui-même descendra du ciel »', 'Sainteté : vivre pour plaire à Dieu'],
    lire: 'Lis ce texte comme une lettre pastorale, pas comme un calendrier prophétique : Paul veut consoler et fortifier, pas satisfaire la curiosité.',
    appl: 'Quelle espérance puis-je donner à ceux qui ont perdu un proche ? Que représente pour moi le retour de Christ ?' },
  53: { ctx: 'Paul écrit quelques mois plus tard, vers 51, à la même Église. Une fausse rumeur dit que le jour du Seigneur est déjà là, et certains ont cessé de travailler.',
    fil: 'Paul corrige : le retour n’est pas encore là, des événements doivent précéder. En attendant, il faut tenir ferme et travailler.',
    th: ['Persécution : Dieu rendra justice', 'Jour du Seigneur : pas encore arrivé', 'Travail : « Si quelqu’un ne veut pas travailler, qu’il ne mange pas non plus »'],
    lire: 'Ce passage de 2:1-12 est l’un des plus débattus. Garde la ligne de Paul : ne pas se laisser troubler, rester ferme.',
    appl: 'L’espérance du retour de Christ me rend-elle plus active ou plus passive dans mes responsabilités ?' },
  54: { ctx: 'Paul écrit vers 62-64 à Timothée, jeune responsable laissé à Éphèse. L’Église y est secouée par de faux enseignants. Paul lui donne des instructions pratiques sur le culte, les responsables, les veuves, les riches.',
    fil: 'Un jeune pasteur doit garder la saine doctrine, organiser l’Église, et vivre de façon exemplaire. L’Église est « la colonne et l’appui de la vérité ».',
    th: ['Saine doctrine : garder le dépôt confié', 'Responsables : les qualités d’un ancien et d’un diacre', 'Piété : « Exerce-toi à la piété »'],
    lire: 'Ces lettres s’adressent à des responsables, mais tout croyant y apprend ce qu’est une Église en bonne santé.',
    appl: 'Qui est mon « Timothée » à qui je transmets, ou mon Paul qui m’encourage ?' },
  55: { ctx: 'Paul écrit de prison à Rome, vers 64-67, peu avant sa mort. Il sait qu’il va être exécuté. C’est son dernier texte, un testament adressé à Timothée.',
    fil: 'Paul passe le relais : reste fidèle, souffre avec courage, garde la Parole. Il peut dire : « J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi ».',
    th: ['Fidélité : transmettre à des hommes fidèles', 'Souffrance : « Souffre avec moi comme un bon soldat »', 'Écriture : toute Écriture est inspirée de Dieu (3:16)'],
    lire: 'Lis la lettre en pensant qu’elle est écrite par un condamné. Chaque conseil prend le poids d’un testament.',
    appl: 'Si je devais laisser un dernier message, que dirais-je ? Qu’ai-je à transmettre avant d’être pris par autre chose ?' },
  56: { ctx: 'Paul écrit vers 63-65 à Tite, laissé en Crète pour y organiser les Églises. La Crète a une mauvaise réputation morale, que Paul cite sans détour.',
    fil: 'La saine doctrine produit une vie transformée. Tite doit établir des responsables, enseigner chaque génération, et rappeler que la grâce enseigne à vivre sagement.',
    th: ['Responsables : des hommes irréprochables', 'Bonnes œuvres : la foi se voit dans la vie', 'Grâce : elle sauve et elle éduque'],
    lire: 'Court et très pratique : trois chapitres, lisibles en dix minutes. Remarque le lien entre doctrine et conduite.',
    appl: 'La grâce que j’ai reçue m’enseigne-t-elle à renoncer à l’impiété ? Où est-ce visible ?' },
  57: { ctx: 'Paul écrit de prison vers 60-62 à Philémon, riche chrétien de Colosses. Son esclave Onésime s’est enfui, a rencontré Paul, s’est converti. Paul le renvoie avec une lettre.',
    fil: 'Paul demande à Philémon de recevoir Onésime « non plus comme un esclave, mais comme un frère bien-aimé ». L’Évangile change les relations sans les changer par décret.',
    th: ['Réconciliation : de l’esclave en fuite au frère', 'Substitution : « Mets cela sur mon compte »', 'Grâce : demander plutôt qu’ordonner'],
    lire: 'La lettre est brève et personnelle. Elle ne dit pas que l’esclavage est bien : elle plante une graine qui le rend impossible entre frères.',
    appl: 'Y a-t-il quelqu’un que je dois recevoir à nouveau, ou pour qui je dois « mettre sur mon compte » ?' },
  58: { ctx: 'Auteur inconnu, vers 60-70 de notre ère, pour des chrétiens d’origine juive tentés de retourner au judaïsme à cause de la persécution. Le livre est un long sermon plus qu’une lettre.',
    fil: 'Jésus est meilleur que tout : meilleur que les anges, que Moïse, que les prêtres, que les sacrifices. Il faut donc tenir ferme dans la foi.',
    th: ['Supériorité de Christ : meilleur sacrifice, meilleur prêtre, meilleure alliance', 'Persévérance : « Tenons ferme la profession de notre espérance »', 'Foi : les héros du chapitre 11'],
    lire: 'Le livre est truffé de citations de l’Ancien Testament. Lis-le avec Lévitique à portée de main : il en donne la clé.',
    appl: 'Qu’est-ce qui me tente de lâcher prise ? Qu’est-ce que Jésus offre de meilleur que ce que je regrette ?' },
  59: { ctx: 'Écrit vers 45-62 par Jacques, frère de Jésus, responsable de l’Église de Jérusalem, à des chrétiens juifs dispersés. C’est probablement l’un des plus anciens textes du Nouveau Testament.',
    fil: 'Une foi vivante se voit dans les actes : épreuves, parole, riches et pauvres, sagesse. Il ne contredit pas Paul : il parle d’une foi qui produit des fruits.',
    th: ['Épreuves : une occasion de persévérance', 'Parole : maîtriser la langue', 'Foi et œuvres : la foi sans les œuvres est morte'],
    lire: 'Jacques ressemble à des proverbes en prose. Il répond à ceux qui disent croire sans que rien ne change. Paul répond à ceux qui veulent gagner leur salut : les deux se complètent.',
    appl: 'Quelle parole ai-je dite cette semaine que je regrette ? Quelle foi ai-je affirmée sans la vivre ?' },
  60: { ctx: 'Pierre écrit de Rome (« Babylone ») vers 62-64 à des chrétiens dispersés en Asie Mineure, étrangers dans leur propre société, moqués et bientôt persécutés.',
    fil: 'Les croyants sont des étrangers, mais ils sont choisis, héritiers d’une espérance vivante. Ils doivent bien vivre, et suivre Christ qui a souffert avant d’être glorifié.',
    th: ['Espérance vivante : née de la résurrection', 'Étrangers : vivre autrement sans se retirer', 'Souffrance : suivre les traces de Christ'],
    lire: 'La lettre s’adresse à des gens marginalisés. Remarque les conseils concrets aux serviteurs, aux femmes, aux maris, aux anciens.',
    appl: 'Comment vivre en étranger sans me replier, et rester attrayant pour ceux qui m’entourent ?' },
  61: { ctx: 'Pierre écrit vers 65-67, peu avant sa mort, à des chrétiens menacés par de faux docteurs qui nient le retour de Christ et vivent dans le désordre.',
    fil: 'Grandir dans la connaissance du Christ protège des erreurs. Le Seigneur reviendra : s’il tarde, c’est par patience, pas par oubli.',
    th: ['Croissance : ajouter à la foi la vertu, la connaissance…', 'Faux docteurs : reconnaître et refuser', 'Patience de Dieu : « Il ne veut pas qu’aucun périsse »'],
    lire: 'Comparaison utile avec Jude, qui parle des mêmes faux docteurs. Pierre mentionne les lettres de Paul comme Écriture.',
    appl: 'Que fais-je pour grandir : lecture, prière, communauté ? Qu’est-ce qui me protège de ce qui pourrait m’égarer ?' },
  62: { ctx: 'Jean, très âgé, écrit vers 85-95 depuis Éphèse à des Églises troublées par des faux enseignants qui niaient que Jésus soit venu dans un vrai corps.',
    fil: 'Dieu est lumière, Dieu est amour. Celui qui est né de lui marche dans la lumière, confesse ses péchés, aime ses frères et croit en Jésus-Christ.',
    th: ['Lumière : marcher dans la vérité', 'Amour : aimer en actes et en vérité', 'Assurance : « Je vous écris afin que vous sachiez que vous avez la vie éternelle »'],
    lire: 'Jean tourne en cercles : lumière, amour, foi reviennent. Ne cherche pas un plan linéaire, lis en méditant chaque retour.',
    appl: 'Ai-je l’assurance d’être aimé de Dieu ? Est-ce que mon amour pour mes frères est visible en actes ?' },
  63: { ctx: 'Jean écrit vers 90 à « la dame élue » (une Église locale ou une chrétienne) pour l’encourager dans la vérité et l’amour et lui demander de ne pas accueillir les faux docteurs.',
    fil: 'Vérité et amour vont ensemble : on marche dans l’amour en obéissant à ses commandements, et on se garde des séducteurs.',
    th: ['Vérité : la doctrine sur Christ', 'Amour : le commandement depuis le commencement', 'Discernement : ne pas soutenir ceux qui l’enseignent mal'],
    lire: 'Une lettre d’un chapitre, que l’on lit en deux minutes. Elle montre que l’hospitalité a une limite : ne pas favoriser la fausse doctrine.',
    appl: 'Comment garder ensemble la vérité et l’amour, sans sacrifier l’un à l’autre ?' },
  64: { ctx: 'Jean écrit vers 90 à Gaïus, un croyant fidèle, qui accueille des missionnaires itinérants. Un certain Diotrèphe, qui aime être le premier, les refuse.',
    fil: 'Soutenir ceux qui servent est une collaboration à la vérité. Imite le bien, non le mal.',
    th: ['Hospitalité : accueillir les serviteurs de Dieu', 'Orgueil : Diotrèphe veut être premier', 'Témoignage : Démétrius est apprécié de tous'],
    lire: 'Une lettre brève et chaleureuse : elle montre la vie des premières Églises, avec ses amitiés et ses tensions.',
    appl: 'Qui puis-je soutenir ou accueillir comme Gaïus ? Ai-je un peu de Diotrèphe en moi ?' },
  65: { ctx: 'Jude, frère de Jacques et de Jésus, écrit vers 65-80 à des Églises où des enseignants immoraux se sont infiltrés. Il voulait écrire sur le salut, mais doit appeler à combattre pour la foi.',
    fil: 'Combattre pour la foi transmise aux saints une fois pour toutes. Se garder dans l’amour de Dieu, sauver ceux qui doutent avec douceur et prudence.',
    th: ['Foi : un dépôt à garder', 'Faux docteurs : exemples bibliques de jugement', 'Persévérance : « Édifiez-vous sur votre très sainte foi »'],
    lire: 'Jude cite des textes que l’on retrouve dans la tradition juive de l’époque. Il les utilise comme exemples, sans leur donner une autorité égale à l’Écriture.',
    appl: 'Pour quoi vaut-il la peine de me battre dans la foi ? Quelle personne puis-je aider avec douceur et clarté ?' },
  66: { ctx: 'Jean, exilé à Patmos vers 95, reçoit une vision pour sept Églises d’Asie Mineure sous la pression de l’empereur romain qui réclame un culte. Le livre emploie un langage très symbolique, dans le style des écrits d’apocalypse juifs.',
    fil: 'Christ est vainqueur. Malgré les persécutions et les puissances du mal, l’Agneau règne ; le mal est jugé et Dieu fait toutes choses nouvelles, avec les siens pour toujours.',
    th: ['Christ vainqueur : l’Agneau est digne', 'Persévérance : « Sois fidèle jusqu’à la mort »', 'Nouvelle création : « Je fais toutes choses nouvelles » (21:5)'],
    lire: 'Les chrétiens se divisent sur la chronologie. Commence par le message partagé : le Christ règne, il revient, Dieu essuie toute larme. Lis d’abord pour être consolé, pas pour calculer.',
    appl: 'Quelle fin est promise à ceux qui tiennent ferme ? Qu’est-ce que cette vision change dans ma peur de l’avenir ?' }
};
